//! R034/02: File navigation back and forward history.
use super::Error;
pub struct Navigate<const N:usize>{items:[u64;N],len:usize,cursor:usize}impl<const N:usize> Navigate<N>{pub fn new()->Self{Self{items:[0;N],len:0,cursor:0}}pub fn push(&mut self,id:u64)->Result<(),Error>{if id==0{return Err(Error::Invalid);}if self.len>0&&self.items[self.cursor]==id{return Ok(());}if self.cursor+1<self.len{self.len=self.cursor+1;}if self.len==N{return Err(Error::Full);}self.items[self.len]=id;self.cursor=self.len;self.len+=1;Ok(())}pub fn back(&mut self)->Result<u64,Error>{if self.cursor==0{return Err(Error::Missing);}self.cursor-=1;Ok(self.items[self.cursor])}pub fn forward(&mut self)->Result<u64,Error>{if self.cursor+1>=self.len{return Err(Error::Missing);}self.cursor+=1;Ok(self.items[self.cursor])}}
#[cfg(test)] mod tests {use super::*;#[test]fn functional_and_boundary_cases(){let mut h=Navigate::<4>::new();h.push(1).unwrap();h.push(2).unwrap();assert_eq!(h.back(),Ok(1));assert_eq!(h.forward(),Ok(2));}}
